import type {
	MessageEndEvent,
	MessageEndEventResult,
} from "@earendil-works/pi-coding-agent";
import { handleAttachCommand } from "./attach.js";
import { registerAgentAutocomplete } from "./autocomplete.js";
import { createRebaseDelivery, handleAgentCommand } from "./runner.js";
import type {
	AgentCommandDetails,
	DetachedEntryData,
	ExtensionAPI,
	ExtensionCommandContext,
	RunningAgent,
} from "./shared.js";
import { DETACHED_ENTRY_TYPE, MESSAGE_TYPE } from "./shared.js";
import { registerUserAgentRenderer } from "./transcript.js";
import { UserAgentWidget } from "./widget.js";

export default function userAgent(pi: ExtensionAPI): void {
	const runningAgents = new Set<RunningAgent>();
	// The session every agent was dispatched from; rebase fast-forwards onto it.
	let mainSessionContext: ExtensionCommandContext | undefined;
	const widget = new UserAgentWidget(
		runningAgents,
		(message) => pi.sendMessage(message, { triggerTurn: true }),
		(sessionId) => pi.appendEntry<DetachedEntryData>(DETACHED_ENTRY_TYPE, { sessionId }),
		createRebaseDelivery(pi, () => mainSessionContext),
	);
	let shuttingDown = false;
	let nextAgentNumber = 0;

	registerUserAgentRenderer(pi);
	registerAgentAutocomplete(pi);

	pi.on("message_end", (event) => confirmMainContextSquash(event, widget));

	pi.registerCommand("agent", {
		description:
			"Run a background SDK agent with current session context; forwards pi CLI options like --thinking (-i/--isolate for none)",
		handler: async (args, ctx) => {
			mainSessionContext = ctx;
			await handleAgentCommand(
				pi,
				runningAgents,
				widget,
				() => shuttingDown,
				() => ++nextAgentNumber,
				"agent",
				args,
				`/agent ${args}`.trim(),
				ctx,
			);
		},
	});

	pi.registerCommand("agent-attach", {
		description: "Reattach a detached agent session by id, back into the widget",
		handler: async (args, ctx) => {
			mainSessionContext = ctx;
			await handleAttachCommand(
				pi,
				runningAgents,
				widget,
				() => shuttingDown,
				() => ++nextAgentNumber,
				args,
				ctx,
			);
		},
	});

	pi.on("session_shutdown", async () => {
		shuttingDown = true;
		widget.dispose();
		const agents = [...runningAgents];
		for (const agent of agents) {
			void agent.session?.abort();
			agent.retire?.();
		}
		await Promise.allSettled(agents.map((agent) => agent.finished));
		for (const agent of agents) {
			agent.session?.dispose();
		}
		runningAgents.clear();
	});
}

export function confirmMainContextSquash(
	event: MessageEndEvent,
	widget: UserAgentWidget,
): MessageEndEventResult | undefined {
	if (event.message.role !== "custom" || event.message.customType !== MESSAGE_TYPE) return;
	const details = event.message.details as AgentCommandDetails | undefined;
	if (!details?.agentId || details.mainContextState !== "will-squash") return;
	widget.confirmMainContextSquash(details.agentId);
	details.mainContextState = "squashed";
	return {
		message: {
			...event.message,
			details: { ...details, mainContextState: "squashed" },
		},
	};
}
import { appendFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import type {
	AgentSession,
	buildSessionContext,
	ExtensionAPI,
	ExtensionCommandContext,
} from "@earendil-works/pi-coding-agent";

export type { AgentSession, ExtensionAPI, ExtensionCommandContext };

export type AgentMessage = ReturnType<typeof buildSessionContext>["messages"][number];
export type Model = NonNullable<ExtensionCommandContext["model"]>;
export type ThinkingLevel = ReturnType<ExtensionAPI["getThinkingLevel"]>;
export type Theme = ExtensionCommandContext["ui"]["theme"];
export type UIContext = ExtensionCommandContext["ui"];

export type AgentCommandName = "agent" | "agent-attach";
export type MainContextState = "separate" | "will-squash" | "squashed" | "rebased";
export type AgentStatus =
	| "starting"
	| "running"
	| "done-waiting-to-post"
	| "idle"
	| "posted"
	| "error";

export type ParsedAgentCommand = {
	isolate: boolean;
	squash: boolean;
	/** Leading pi CLI tokens (minus the extension's own options) to forward to the child, e.g. ["--thinking", "high"]. */
	forwardedArgs: string[];
	task: string;
	/** Advisory messages surfaced to the user (e.g. a recognized option was typed inside the prose body). */
	warnings: string[];
};

export type AgentEntryData = {
	content: string;
	details: AgentCommandDetails;
};

export type DetachedEntryData = {
	sessionId: string;
};

export type AttachedEntryData = {
	sessionId: string;
};

/** Persisted in the child session at dispatch: the facts attach cannot recover from messages alone. */
export type DispatchRecordData = {
	/** The pi CLI tokens the dispatch forwarded, e.g. ["--tools", "read,grep"]. */
	forwardedArgs: string[];
	/** The plain task, without the dispatch preamble. */
	task: string;
	isolate: boolean;
};

export type RebaseStats = {
	messageCount: number;
	tokenEstimate: number;
	compactionCount: number;
};

export type RebasedEntryData = {
	sessionId: string;
	/** Absent on entries persisted before stats existed. */
	stats?: RebaseStats;
};

/**
 * A child compaction captured from its compaction_end event. keptTailCount records how many
 * messages the compaction kept verbatim, so a rebase replay can restore the exact boundary.
 */
export type ChildCompactionMessage = Extract<AgentMessage, { role: "compactionSummary" }> & {
	keptTailCount?: number;
};

export type AgentResultMessage = {
	customType: string;
	content: string;
	display: boolean;
	details: AgentCommandDetails;
};

export type AgentCommandDetails = {
	agentId?: string;
	command: AgentCommandName;
	mainContextState?: MainContextState;
	/** Absent on command-error cards: an error has no inherited-or-isolated notion. */
	inheritedContext?: boolean;
	model: string;
	modelLabel: string;
	task: string;
	ok: boolean;
	durationMs?: number;
	toolUses?: number;
	turnCount?: number;
	responseText?: string;
	/** Retained for completed entries written before responseText was persisted. */
	responsePreview?: string;
	error?: string;
};

export type RunningAgent = {
	id: string;
	/** The child's own Pi session, resumable with `/resume <sessionId>` after the agent is detached. */
	sessionId: string;
	command: AgentCommandName;
	inheritedContext: boolean;
	model: string;
	modelLabel: string;
	task: string;
	/** The slash command line as the user typed it, e.g. `/agent -s fix the bug`. */
	invocation: string;
	/** -s/--squash: post invocation+result to the main agent and trigger its turn, instead of waiting quietly for the next user prompt. */
	notifyMainAgent: boolean;
	/** Fingerprint of the main context the child was dispatched from ("[]" for -i); the rebase fast-forward base. */
	dispatchBaseFingerprint: string;
	mainContextState: MainContextState;
	status: AgentStatus;
	startedAt: number;
	/** Start of the current turn — equals startedAt until the user resumes an idle agent. */
	turnStartedAt: number;
	completedAt?: number;
	activeTools: Map<string, string>;
	toolUses: number;
	turnCount: number;
	responseText: string;
	/** Append-only child conversation, independent from model context compaction. */
	conversationMessages: AgentMessage[];
	latestFinalizedMessage?: AgentMessage;
	error?: string;
	session?: AgentSession;
	/** Latest completed turn's result message, deliverable to the main agent via the overlay's squash action. */
	pendingSquashMessage?: AgentResultMessage;
	/** Starts another turn on an idle agent; assigned while the lifecycle loop awaits the next instruction. */
	resume?: (instruction: string) => void;
	/** Ends an idle agent's lifecycle without another turn; assigned alongside resume. */
	retire?: () => void;
	finished: Promise<void>;
	/** Set when the user closes an in-flight agent from the widget — suppresses the error entry and transcript post. */
	aborted?: boolean;
	/** Set when the user interrupts only the active turn, leaving the child session alive. */
	interruptRequested?: boolean;
};

export type CompletedAgent = {
	id: string;
	sessionId: string;
	command: AgentCommandName;
	modelLabel: string;
	task: string;
	dispatchBaseFingerprint: string;
	mainContextState: MainContextState;
	pendingSquashMessage?: AgentResultMessage;
	ok: boolean;
	responseText: string;
	messages: AgentMessage[];
	error?: string;
	startedAt: number;
	durationMs: number;
	toolUses: number;
	turnCount: number;
	contextPercent?: number;
};

/** The mechanism that fast-forwards a child conversation onto the main session, injected into the widget. */
export type RebaseDelivery = {
	/** Whether the main session's live context still equals this agent's dispatch base. */
	canDeliver(agent: RunningAgent | CompletedAgent): boolean;
	/** Append the processed child conversation onto the main session. */
	deliver(agent: RunningAgent | CompletedAgent, messages: AgentMessage[]): void;
};

/** How long a confirmation stays armed, and how long a transient footer notice shows. */
export const CONFIRMATION_WINDOW_MS = 4000;

/**
 * A two-press confirmation with a timeout: the first press arms it, a repeat press on the
 * same target within the window confirms. A press on another target re-arms, cancel or
 * expiry disarms. One instance serves every confirmable action on a surface.
 */
export class TimedConfirmation<Target> {
	private armedOn: Target | undefined;
	private expiry: ReturnType<typeof setTimeout> | undefined;

	constructor(
		private readonly onExpire: () => void,
		private readonly windowMs: number = CONFIRMATION_WINDOW_MS,
	) {}

	/** One press of the action key: true means confirmed, false means armed and waiting. */
	press(target: Target): boolean {
		if (this.armedOn === target) {
			this.cancel();
			return true;
		}
		this.armedOn = target;
		if (this.expiry) clearTimeout(this.expiry);
		this.expiry = setTimeout(() => {
			this.armedOn = undefined;
			this.expiry = undefined;
			this.onExpire();
		}, this.windowMs);
		return false;
	}

	cancel(): void {
		this.armedOn = undefined;
		if (this.expiry) clearTimeout(this.expiry);
		this.expiry = undefined;
	}

	isArmedOn(target: Target): boolean {
		return this.armedOn !== undefined && this.armedOn === target;
	}
}

export const MESSAGE_TYPE = "pi-user-agents";
export const DETACHED_ENTRY_TYPE = "pi-user-agents-detached";
export const REBASED_ENTRY_TYPE = "pi-user-agents-rebased";
export const ATTACHED_ENTRY_TYPE = "pi-user-agents-attached";
export const DISPATCH_ENTRY_TYPE = "pi-user-agents-dispatch";
export const WIDGET_KEY = "pi-user-agents";
export const STEERING_LOG_PATH = `${tmpdir()}/pi-user-agents-steer.log`;

export function logSteering(
	agentId: string,
	event: string,
	details: Record<string, unknown> = {},
): void {
	void appendFile(
		STEERING_LOG_PATH,
		`${new Date().toISOString()} ${JSON.stringify({ agentId, event, ...details })}\n`,
	).catch(() => undefined);
}
export const MAX_WIDGET_LINES = 9;
export const SPINNER = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];

export const TOOL_DISPLAY: Record<string, string> = {
	read: "reading",
	bash: "running command",
	edit: "editing",
	write: "writing",
	grep: "searching",
	find: "finding files",
	ls: "listing",
};

export function formatModel(model: Model): string {
	return `${model.provider}/${model.id}${model.name && model.name !== model.id ? ` (${model.name})` : ""}`;
}

export function formatModelLabel(model: Model): string {
	return model.name && model.name !== model.id ? model.name : model.id;
}

export function contextLabel(inheritedContext: boolean): string {
	return inheritedContext ? "inherited context" : "isolated";
}

export function mainContextLabel(state: MainContextState | undefined): string | undefined {
	if (state === "will-squash") return "will squash into context";
	if (state === "squashed") return "squashed messages into context";
	if (state === "rebased") return "rebased into context";
	return undefined;
}

export function formatTurns(turnCount: number): string {
	return `↻${turnCount}`;
}

export function formatToolUses(toolUses: number): string {
	return `${toolUses} tool use${toolUses === 1 ? "" : "s"}`;
}

export function formatMs(ms: number): string {
	if (!Number.isFinite(ms)) return "0.0s";
	if (ms < 60_000) return `${(ms / 1000).toFixed(1)}s`;
	const minutes = Math.floor(ms / 60_000);
	const seconds = Math.round((ms % 60_000) / 1000);
	return `${minutes}m ${seconds}s`;
}

export function truncatePlain(text: string, length: number): string {
	const line =
		text
			.split("\n")
			.find((part) => part.trim())
			?.trim() ?? "";
	if (line.length <= length) return line;
	return `${line.slice(0, Math.max(0, length - 1))}…`;
}

export function extractTag(
	content: string,
	tag: "task" | "response" | "error" | "duration_ms",
): string | undefined {
	const match = content.match(new RegExp(`<${tag}>\\n?([\\s\\S]*?)\\n?</${tag}>`));
	return match?.[1]?.trim();
}

export function escapeAttribute(value: string): string {
	return value
		.replace(/&/g, "&amp;")
		.replace(/"/g, "&quot;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;");
}

export function errorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}
import { buildSessionContext } from "@earendil-works/pi-coding-agent";
import type { AgentMessage, ExtensionCommandContext } from "./shared.js";
import { MESSAGE_TYPE } from "./shared.js";

type MainSessionManager = ExtensionCommandContext["sessionManager"];

/**
 * Fingerprint a context snapshot for the rebase fast-forward precondition: the main session's
 * live context must still fingerprint-equal the base the child was dispatched from.
 *
 * Compares content, not file bookkeeping: rebuilding custom, compaction, and branch summaries
 * from a session file re-stamps their timestamps (and a branch summary's fromId), so a base
 * round-tripped through a child's file would never equal main's live context otherwise.
 *
 * @example conversationFingerprint([]) === conversationFingerprint([]) // true
 */
export function conversationFingerprint(messages: readonly AgentMessage[]): string {
	return JSON.stringify(messages.map(fingerprintedMessage));
}

function fingerprintedMessage(message: AgentMessage): Omit<AgentMessage, "timestamp"> {
	const { timestamp: _timestamp, ...content } = message;
	if (content.role !== "branchSummary") return content;
	const { fromId: _fromId, ...branchContent } = content;
	return branchContent;
}

/** Rebuilding a session-sized context string is only worth doing when the branch tip moved. */
const contextFingerprintCache = new WeakMap<object, { leafId: string | null; fingerprint: string }>();

/** Fingerprint of the main session's current LLM context, cached by branch leaf. */
export function mainContextFingerprint(sessionManager: MainSessionManager): string {
	const leafId = sessionManager.getLeafId();
	const cached = contextFingerprintCache.get(sessionManager);
	if (cached && cached.leafId === leafId) return cached.fingerprint;
	const fingerprint = conversationFingerprint(
		buildSessionContext(sessionManager.getBranch()).messages,
	);
	contextFingerprintCache.set(sessionManager, { leafId, fingerprint });
	return fingerprint;
}

/**
 * Select the child conversation messages to rebase onto the main session, so the record reads
 * as if the user prompted the main session directly. The child's history passes through
 * verbatim — compactions included, so main inherits the child's context boundary — except the
 * first user message, which carries the extension's internal background-process prefix and is
 * replaced by the plain task, and this extension's own custom messages, which are the one
 * trace of the user-agents machinery.
 */
export function selectRebaseMessages(
	task: string,
	messages: readonly AgentMessage[],
): AgentMessage[] {
	let firstUserMessage = true;
	const selected: AgentMessage[] = [];
	for (const message of messages) {
		if (message.role === "custom" && message.customType === MESSAGE_TYPE) continue;
		if (message.role === "user" && firstUserMessage) {
			firstUserMessage = false;
			selected.push({ ...message, content: task });
			continue;
		}
		selected.push(message);
	}
	return selected;
}

