export function reportCommandError(
	pi: ExtensionAPI,
	command: AgentCommandName,
	args: string,
	ctx: ExtensionCommandContext,
	message: string,
): void {
	if (ctx.hasUI) {
		ctx.ui.notify(message, "error");
		return;
	}
	pi.sendMessage<AgentCommandDetails>({
		customType: MESSAGE_TYPE,
		content: formatCommandErrorMessage(command, args, message),
		display: true,
		details: {
			command,
			model: "",
			modelLabel: "",
			task: args.trim(),
			ok: false,
			error: message,
		},
	});
}

/**
 * Select the squashed role messages from a child transcript.
 *
 * @example selectSquashedMessages([{ role: "user", content: "hello", timestamp: 0 }]).length // 1
 */
type SquashedMessage = Extract<AgentMessage, { role: "user" | "assistant" }>;

export function selectSquashedMessages(messages: readonly AgentMessage[]): SquashedMessage[] {
	const selected: SquashedMessage[] = [];
	let latestAssistant: Extract<AgentMessage, { role: "assistant" }> | undefined;
	for (const message of messages) {
		if (message.role === "assistant" && roleMessageText(message).trim()) {
			latestAssistant = message;
			continue;
		}
		if (message.role !== "user") continue;
		if (latestAssistant) selected.push(latestAssistant);
		latestAssistant = undefined;
		selected.push(message);
	}
	if (latestAssistant) selected.push(latestAssistant);
	return selected;
}

export function buildMessageDetails(agent: RunningAgent, ok: boolean): AgentCommandDetails {
	return {
		agentId: agent.id,
		command: agent.command,
		mainContextState: agent.mainContextState,
		inheritedContext: agent.inheritedContext,
		model: agent.model,
		modelLabel: agent.modelLabel,
		task: agent.task,
		ok,
		durationMs: (agent.completedAt ?? Date.now()) - agent.turnStartedAt,
		toolUses: agent.toolUses,
		turnCount: agent.turnCount,
		responseText: ok ? agent.responseText : undefined,
		error: ok ? undefined : agent.error,
	};
}

/** Build the canonical parent-session message used by immediate and late result delivery. */
export function buildAgentResultMessage(
	agent: RunningAgent,
	outcome: { ok: true; response: string } | { ok: false; error: string },
	options: { display: boolean },
): AgentResultMessage {
	return {
		customType: MESSAGE_TYPE,
		content: outcome.ok
			? formatResultMessage(agent)
			: formatErrorMessage(agent, outcome.error),
		display: options.display,
		details: buildMessageDetails(agent, outcome.ok),
	};
}

const SQUASHED_CONVERSATION_PREFACE =
	"The user has dispatched a background sub-agent with a task. The sub-agent is done. The following is the back and forth between them:";

export function formatResultMessage(agent: RunningAgent): string {
	const messages = selectSquashedMessages(agent.conversationMessages);
	const lines = [
		SQUASHED_CONVERSATION_PREFACE,
		`<user_agent model="${escapeAttribute(agent.model)}" inherited_context="${agent.inheritedContext}">`,
	];
	let firstUserMessage = true;
	for (const [index, message] of messages.entries()) {
		const tag = message.role === "user" ? "user_message" : "assistant_response";
		const content =
			message.role === "user" && firstUserMessage ? agent.task : roleMessageText(message);
		if (message.role === "user") firstUserMessage = false;
		lines.push(
			`  <${tag} i=${index + 1}>`,
			...content.split("\n").map((line) => `  ${line}`),
			`  </${tag}>`,
		);
	}
	lines.push("</user_agent>");
	return lines.join("\n");
}

function roleMessageText(message: SquashedMessage): string {
	if (typeof message.content === "string") return message.content;
	return message.content
		.flatMap((part) => (part.type === "text" ? [part.text] : []))
		.join("\n");
}

export function formatErrorMessage(agent: RunningAgent, message: string): string {
	return [
		`<user_agent_error command="/${agent.command}" model="${escapeAttribute(agent.model)}" inherited_context="${agent.inheritedContext}">`,
		...invocationLines(agent),
		"<task>",
		agent.task,
		"</task>",
		"<error>",
		message,
		"</error>",
		"<duration_ms>",
		String((agent.completedAt ?? Date.now()) - agent.turnStartedAt),
		"</duration_ms>",
		"</user_agent_error>",
	].join("\n");
}

function invocationLines(agent: RunningAgent): string[] {
	return ["<user_invocation>", agent.invocation, "</user_invocation>"];
}

export function formatCommandErrorMessage(
	command: AgentCommandName,
	args: string,
	message: string,
): string {
	return [
		`<user_agent_error command="/${command}">`,
		"<task>",
		args.trim(),
		"</task>",
		"<error>",
		message,
		"</error>",
		"</user_agent_error>",
	].join("\n");
}

export function formatStartNotification(agent: RunningAgent): string {
	return [
		`Started /${agent.command}`,
		agent.modelLabel,
		contextLabel(agent.inheritedContext),
		mainContextLabel(agent.mainContextState),
	]
		.filter(Boolean)
		.join(" · ");
}

export function registerUserAgentRenderer(pi: ExtensionAPI): void {
	pi.registerMessageRenderer<AgentCommandDetails>(
		MESSAGE_TYPE,
		(message, { expanded }, theme) =>
			liveAgentCard(
				() => customMessageContentText(message.content),
				() => message.details,
				expanded,
				theme,
			),
	);
	pi.registerEntryRenderer<AgentEntryData>(
		MESSAGE_TYPE,
		(entry, { expanded }, theme) =>
			entry.data
				? liveAgentCard(
						() => entry.data!.content,
						() => entry.data!.details,
						expanded,
						theme,
					)
				: undefined,
	);
	// Pi's chat container does not pad renderer components; its own chat lines self-pad with paddingX 1.
	pi.registerEntryRenderer<DetachedEntryData>(DETACHED_ENTRY_TYPE, (entry, _state, theme) =>
		entry.data
			? new Text(theme.fg("dim", `Detached session ${entry.data.sessionId}`), 1, 0)
			: undefined,
	);
	pi.registerEntryRenderer<AttachedEntryData>(ATTACHED_ENTRY_TYPE, (entry, _state, theme) =>
		entry.data
			? new Text(theme.fg("dim", `Attached session ${entry.data.sessionId}`), 1, 0)
			: undefined,
	);
	pi.registerEntryRenderer<RebasedEntryData>(REBASED_ENTRY_TYPE, (entry, _state, theme) =>
		entry.data ? new Text(theme.fg("dim", formatRebasedLine(entry.data)), 1, 0) : undefined,
	);
}

function formatRebasedLine(data: RebasedEntryData): string {
	const base = `Rebased session ${data.sessionId} into this conversation`;
	if (!data.stats) return base;
	const parts = [
		`added ${data.stats.messageCount} message${data.stats.messageCount === 1 ? "" : "s"}`,
		`~${formatTokenCount(data.stats.tokenEstimate)} tokens`,
	];
	if (data.stats.compactionCount > 0)
		parts.push(
			`${data.stats.compactionCount} compaction event${data.stats.compactionCount === 1 ? "" : "s"}`,
		);
	return `${base} (${parts.join(", ")})`;
}

/**
 * @example formatTokenCount(135_264) // "135K"
 * @example formatTokenCount(12) // "12"
 */
function formatTokenCount(tokens: number): string {
	return tokens < 1000 ? `${tokens}` : `${Math.round(tokens / 1000)}K`;
}

function liveAgentCard(
	content: () => string,
	details: () => AgentCommandDetails | undefined,
	expanded: boolean,
	theme: Theme,
): Component {
	const body = renderAgentCardBody(content(), details(), expanded, theme);
	return {
		render: (width) => renderAgentCard(content(), details(), body, theme).render(width),
		invalidate: () => body.invalidate(),
	};
}

function renderAgentCard(
	content: string,
	details: AgentCommandDetails | undefined,
	body: Component,
	theme: Theme,
): Container {
	const ok = details?.ok ?? !content.includes("<user_agent_error");
	const command = details ? `/${details.command}` : "/agent";
	const icon = ok ? theme.fg("success", "✓") : theme.fg("error", "✗");
	const statusText = ok ? theme.fg("dim", "completed") : theme.fg("error", "failed");
	const parts = buildRendererParts(content, details);
	const task = details?.task ?? extractTag(content, "task");

	let text = `${icon} ${theme.bold(command)} ${statusText}`;
	if (parts.length > 0) text += ` ${theme.fg("dim", "·")} ${theme.fg("dim", parts.join(" · "))}`;
	if (task) text += `\n  ${theme.fg("dim", `task: ${truncatePlain(task, 88)}`)}`;
	const card = new Container();
	card.addChild(new Text(text, 1, 0));
	card.addChild(body);
	return card;
}

function renderAgentCardBody(
	content: string,
	details: AgentCommandDetails | undefined,
	expanded: boolean,
	theme: Theme,
): Component {
	const ok = details?.ok ?? !content.includes("<user_agent_error");
	const output =
		details?.responseText ??
		details?.error ??
		extractTag(content, ok ? "response" : "error") ??
		"No output.";
	if (expanded)
		return ok
			? new Markdown(output, 3, 0, getMarkdownTheme())
			: new Text(theme.fg("error", output), 3, 0);

	const previewText = `⎿  ${truncatePlain(details?.responsePreview ?? output, 110)}`;
	if (!ok) return new Text(`  ${theme.fg("error", previewText)}`, 1, 0);
	return new Markdown(previewText, 3, 0, getMarkdownTheme(), {
		color: (value) => theme.fg("dim", value),
	});
}

function customMessageContentText(content: unknown): string {
	if (typeof content === "string") return content;
	if (!Array.isArray(content)) return String(content ?? "");
	return content
		.filter(
			(part): part is { type: "text"; text: string } =>
				part?.type === "text" && typeof part.text === "string",
		)
		.map((part) => part.text)
		.join("\n");
}

function buildRendererParts(content: string, details: AgentCommandDetails | undefined): string[] {
	const parts: string[] = [];
	if (details?.modelLabel) parts.push(details.modelLabel);
	else if (details?.model) parts.push(details.model);
	if (details?.inheritedContext !== undefined) parts.push(contextLabel(details.inheritedContext));
	const mainContext = mainContextLabel(details?.mainContextState);
	if (mainContext) parts.push(mainContext);
	if (details?.turnCount) parts.push(formatTurns(details.turnCount));
	if (details?.toolUses) parts.push(formatToolUses(details.toolUses));
	if (details?.durationMs !== undefined) parts.push(formatMs(details.durationMs));
	else {
		const duration = extractTag(content, "duration_ms");
		if (duration) parts.push(formatMs(Number(duration)));
	}
	return parts;
}
import type { CompletedAgent, RunningAgent, Theme } from "./shared.js";

const CONTEXT_METER_SYMBOLS = [" ", "▁", "▂", "▃", "▄", "▅", "▆", "▇", "█"] as const;
const CONTEXT_MUTED_THRESHOLD = 40;
const CONTEXT_WARNING_THRESHOLD = 65;
const CONTEXT_ERROR_THRESHOLD = 85;

type ContextMeterAgent = RunningAgent | CompletedAgent;
type ContextMeterColor = "dim" | "muted" | "warning" | "error";

/** @example contextMeterColor(85) // "error" */
export function contextMeterColor(percent: number): ContextMeterColor {
	if (percent >= CONTEXT_ERROR_THRESHOLD) return "error";
	if (percent >= CONTEXT_WARNING_THRESHOLD) return "warning";
	if (percent >= CONTEXT_MUTED_THRESHOLD) return "muted";
	return "dim";
}

export function renderContextMeter(
	percent: number | null | undefined,
	theme: Pick<Theme, "fg">,
): string {
	if (percent === null || percent === undefined) return "";
	const boundedPercent = Math.max(0, Math.min(100, percent));
	const level = Math.min(
		CONTEXT_METER_SYMBOLS.length - 1,
		Math.floor(boundedPercent / (100 / CONTEXT_METER_SYMBOLS.length)),
	);
	return theme.fg(contextMeterColor(boundedPercent), CONTEXT_METER_SYMBOLS[level]);
}

/** Render the current or final context usage for either agent state. */
export function renderAgentContextMeter(
	agent: ContextMeterAgent,
	theme: Pick<Theme, "fg">,
): string {
	const percent = "status" in agent
		? agent.session?.getContextUsage()?.percent
		: agent.contextPercent;
	return renderContextMeter(percent, theme);
}

