					this.canRebaseMainContext() ? th.fg("dim", "r rebase") : "",
					isLiveAgent(this.agent) ? th.fg("dim", "Ctrl+x interrupt") : "",
					mainContext ? th.fg("dim", mainContext) : "",
					isLiveAgent(this.agent) ? th.fg("dim", "Esc hide") : "",
