	invalidate(): void {}

	dispose(): void {}

	/** Surface why r did nothing, in the footer, for a few seconds. Memory-only, like `✓ copied`. */
	private showRebaseWarning(warning: string): void {
		this.rebaseWarning = warning;
		if (this.rebaseWarningTimer) clearTimeout(this.rebaseWarningTimer);
		this.rebaseWarningTimer = setTimeout(() => {
			this.rebaseWarning = undefined;
			this.tui.requestRender();
		}, CONFIRMATION_WINDOW_MS);
		this.tui.requestRender();
	}

	private requestDetach(): void {
		if (this.confirmation.press("detach")) {
			this.done("detach");
			return;
		}
		this.tui.requestRender();
	}

	private copyResponse(): void {
		const text =
			isRunningAgent(this.agent) || this.agent.ok
				? this.agent.responseText
				: (this.agent.error ?? "");
		const child = childProcess.execFile("pbcopy", (error) => {
			if (error) return;
			this.justCopied = true;
			this.tui.requestRender();
			setTimeout(() => {
				this.justCopied = false;
				this.tui.requestRender();
			}, 1500);
		});
		child.stdin?.end(text);
	}

	private innerWidth(width: number): number {
		return Math.max(1, width - 4);
	}

	private viewportHeight(): number {
		const maxRows = Math.floor((this.tui.terminal.rows * VIEWER_HEIGHT_PCT) / 100);
		return Math.max(VIEWER_MIN_VIEWPORT, maxRows - VIEWER_CHROME_LINES - (this.composer ? 1 : 0));
	}

	private canSteer(): boolean {
		return isSteerableAgent(this.agent) && this.agent.session !== undefined;
	}

	private openComposer(): void {
		if (!isRunningAgent(this.agent) || !this.agent.session) {
			logSteering(this.agent.id, "composer-refused", { running: isRunningAgent(this.agent) });
			return;
		}
		const agent = this.agent;
		const session = agent.session;
		logSteering(agent.id, "composer-opened", {
			status: agent.status,
			streaming: session.isStreaming,
		});
		const input = new Input();
		input.focused = true;
		input.onSubmit = (value: string) => {
			const message = value.trim();
			this.composer = undefined;
			if (!message) {
				logSteering(agent.id, "steer-empty", {
					status: agent.status,
					streaming: session.isStreaming,
				});
				this.tui.requestRender();
				return;
			}
			this.autoScroll = true;
			logSteering(agent.id, "steer-submitted", {
				status: agent.status,
				streaming: session.isStreaming,
				messageLength: message.length,
			});
			if (agent.status === "idle") {
				agent.resume?.(message);
			} else {
				void session.steer(message).then(
					() => logSteering(agent.id, "steer-queued", { streaming: session.isStreaming }),
					(error) =>
						logSteering(agent.id, "steer-rejected", {
							error: errorMessage(error),
							streaming: session.isStreaming,
						}),
				);
			}
			this.tui.requestRender();
		};
		input.onEscape = () => {
			this.composer = undefined;
			logSteering(agent.id, "composer-cancelled", {
				status: agent.status,
				streaming: session.isStreaming,
			});
			this.tui.requestRender();
		};
		this.composer = input;
		this.tui.requestRender();
	}

	private contentLines(width: number): string[] {
		const key = this.contentCacheKey(width);
		if (this.renderedContent?.key === key) return this.renderedContent.lines;
		const lines = this.buildContentLines(width);
		this.renderedContent = { key, lines };
		return lines;
	}

	/**
	 * Invalidate on anything that changes the rendered transcript.
	 *
	 * Streamed content only ever grows, so the summed length of the last message's parts is
	 * enough to notice it changing without walking the whole transcript.
	 */
	private contentCacheKey(width: number): string {
		const messages = transcriptMessages(this.agent);
		const running = isRunningAgent(this.agent);
		return [
			width,
			messages.length,
			messageContentLength(messages[messages.length - 1]),
			running ? this.agent.status : "done",
			running ? this.agent.responseText.length : 0,
			// A live agent appends an activity line drawn from this message, not from the transcript.
			running ? messageContentLength(this.agent.latestFinalizedMessage) : 0,
			this.agent.error?.length ?? 0,
		].join("|");
	}

	private buildContentLines(width: number): string[] {
		if (width <= 0) return [];
		const lines = this.transcriptLines(width);
		if (isLiveAgent(this.agent)) {
			if (lines.length === 0) return [this.theme.fg("dim", "(waiting for first message…)")];
			const activity = describeActivity(this.agent);
			if (activity.text.trim()) {
				const prefix = this.theme.fg("accent", "▍ ");
				lines.push(
					"",
					`${prefix}${renderActivity(activity, width - visibleWidth(prefix), this.theme)}`,
				);
			}
			return lines;
		}
		if (agentFailed(this.agent)) {
			const errorLines = wrapTextWithAnsi(this.agent.error?.trim() || "Unknown error", width).map(
				(line) => this.theme.fg("error", line),
			);
			if (lines.length === 0) return errorLines;
			return [...lines, this.theme.fg("dim", "───"), ...errorLines];
		}
		if (lines.length === 0) return [this.theme.fg("dim", "(empty response)")];
		return lines;
	}

	private transcriptLines(width: number): string[] {
		const messages = transcriptMessages(this.agent);
		const toolIndex = indexToolMessages(messages);
		const lines: string[] = [];
		for (const message of messages) {
			const block = this.messageLines(message, width, toolIndex);
			if (block.length === 0) continue;
			if (lines.length > 0) lines.push(this.theme.fg("dim", "───"));
			lines.push(...block);
		}
		return lines.map((line) => truncateToWidth(line, width));
	}

	private messageLines(message: AgentMessage, width: number, toolIndex: ToolIndex): string[] {
		const th = this.theme;
		switch (message.role) {
			case "user":
			case "custom": {
				const text =
					typeof message.content === "string"
						? message.content
						: message.content
								.flatMap((part) => (part.type === "text" ? [part.text] : []))
								.join("\n");
				if (!text.trim()) return [];
				return [th.fg("accent", "[User]"), ...wrapTextWithAnsi(text.trim(), width)];
			}
			case "assistant": {
				const textLines: string[] = [];
				const toolLines: string[] = [];
				for (const part of message.content) {
					if (part.type === "text" && part.text.trim())
						textLines.push(
							...new Markdown(part.text.trim(), 0, 0, markdownThemeFromTheme(th)).render(width),
						);
					else if (part.type === "toolCall") {
						const call = part as ToolCallPart;
						toolLines.push(
							...renderToolCall(call, toolIndex.resultByCallId.get(call.id), width, th),
						);
					}
				}
				if (textLines.length === 0) return toolLines;
				return [th.bold("[Assistant]"), ...textLines, ...toolLines];
			}
			case "toolResult": {
				// The call renders its own result, so only an orphaned result needs a block here.
				if (toolIndex.callIds.has(message.toolCallId)) return [];
				return renderOrphanToolResult(
					message.toolName,
					{ content: message.content, details: message.details, isError: message.isError },
					width,
					th,
				);
			}
			case "bashExecution": {
				const lines = [th.fg("muted", `$ ${message.command}`)];
				const output = capTranscript(message.output);
				if (output)
					lines.push(...wrapTextWithAnsi(output, width).map((line) => th.fg("dim", line)));
				return lines;
			}
			default:
				return [];
		}
	}
}

const TRANSCRIPT_OUTPUT_CAP = 500;

export function transcriptMessages(agent: ViewableAgent): AgentMessage[] {
	return isRunningAgent(agent) ? agent.conversationMessages : agent.messages;
}

/** Cheap change detector for the streaming tail of a transcript. String lengths only. */
function messageContentLength(message: AgentMessage | undefined): number {
	if (!message) return 0;
	switch (message.role) {
		case "assistant":
			return message.content.reduce(
				(total, part) =>
					total +
					(part.type === "text"
						? part.text.length
						: part.type === "thinking"
							? part.thinking.length
							: JSON.stringify(part.arguments).length),
				0,
			);
		case "toolResult":
			return message.content.reduce(
				(total, part) => total + (part.type === "text" ? part.text.length : 1),
				0,
			);
		case "bashExecution":
			return message.command.length + message.output.length;
		case "user":
		case "custom":
			// A string's characters or an array's parts. Either count moves when the content moves.
			return message.content.length;
		default:
			return message.summary.length;
	}
}

function capTranscript(text: string): string {
	const trimmed = text.trim();
	if (trimmed.length <= TRANSCRIPT_OUTPUT_CAP) return trimmed;
	return `${trimmed.slice(0, TRANSCRIPT_OUTPUT_CAP)}…`;
}

export function isRunningAgent(agent: ViewableAgent): agent is RunningAgent {
	return "status" in agent;
}

export function isLiveAgent(agent: ViewableAgent): agent is RunningAgent {
	return isRunningAgent(agent) && (agent.status === "starting" || agent.status === "running");
}

function isSteerableAgent(agent: ViewableAgent): agent is RunningAgent {
	return isLiveAgent(agent) || (isRunningAgent(agent) && agent.status === "idle");
}

function agentFailed(agent: ViewableAgent): boolean {
	return agent.error !== undefined || (!isRunningAgent(agent) && !agent.ok);
}

function dimMarkdownThemeFromTheme(theme: Theme): MarkdownTheme {
	const dim = (text: string) => theme.fg("dim", text);
	return {
		heading: (text) => theme.bold(dim(text)),
		link: (text) => theme.underline(dim(text)),
		linkUrl: dim,
		code: (text) => theme.fg("mdCode", text),
		codeBlock: dim,
		codeBlockBorder: dim,
		quote: dim,
		quoteBorder: dim,
		hr: dim,
		listBullet: dim,
		bold: (text) => theme.bold(text),
		italic: (text) => theme.italic(text),
		underline: (text) => theme.underline(text),
		strikethrough: (text) => theme.strikethrough(text),
	};
}

function markdownThemeFromTheme(theme: Theme): MarkdownTheme {
	return {
		heading: (text) => theme.fg("mdHeading", text),
		link: (text) => theme.fg("mdLink", text),
		linkUrl: (text) => theme.fg("mdLinkUrl", text),
		code: (text) => theme.fg("mdCode", text),
		codeBlock: (text) => theme.fg("mdCodeBlock", text),
		codeBlockBorder: (text) => theme.fg("mdCodeBlockBorder", text),
		quote: (text) => theme.fg("mdQuote", text),
		quoteBorder: (text) => theme.fg("mdQuoteBorder", text),
		hr: (text) => theme.fg("mdHr", text),
		listBullet: (text) => theme.fg("mdListBullet", text),
		bold: (text) => theme.bold(text),
		italic: (text) => theme.italic(text),
		underline: (text) => theme.underline(text),
		strikethrough: (text) => theme.strikethrough(text),
	};
}

function fitFooterSegments(theme: Theme, width: number, segments: string[]): string {
	const separator = ` ${theme.fg("dim", "·")} `;
	let start = 0;
	while (start < segments.length - 1) {
		const candidate = segments.slice(start).join(separator);
		if (visibleWidth(candidate) <= width) return candidate;
		start += 1;
	}
	return truncateToWidth(segments.at(-1) ?? "", width);
}
import { getMarkdownTheme } from "@earendil-works/pi-coding-agent";
import { type Component, Container, Markdown, Text } from "@earendil-works/pi-tui";
import type {
	AgentCommandDetails,
	AgentCommandName,
	AgentEntryData,
	AgentMessage,
	AgentResultMessage,
	AttachedEntryData,
	DetachedEntryData,
	ExtensionAPI,
	ExtensionCommandContext,
	RebasedEntryData,
	RunningAgent,
	Theme,
} from "./shared.js";
import {
	ATTACHED_ENTRY_TYPE,
	contextLabel,
	DETACHED_ENTRY_TYPE,
	escapeAttribute,
	extractTag,
	formatMs,
	formatToolUses,
	formatTurns,
	mainContextLabel,
	MESSAGE_TYPE,
	REBASED_ENTRY_TYPE,
	truncatePlain,
} from "./shared.js";

export function reportCommandError(
	pi: ExtensionAPI,
	command: AgentCommandName,
	args: string,
	ctx: ExtensionCommandContext,
	message: string,
): void {
	if (ctx.hasUI) {
		ctx.ui.notify(message, "error");
		return;
	}
	pi.sendMessage<AgentCommandDetails>({
		customType: MESSAGE_TYPE,
		content: formatCommandErrorMessage(command, args, message),
		display: true,
		details: {
			command,
			model: "",
			modelLabel: "",
			task: args.trim(),
			ok: false,
			error: message,
		},
	});
}

/**
 * Select the squashed role messages from a child transcript.
 *
 * @example selectSquashedMessages([{ role: "user", content: "hello", timestamp: 0 }]).length // 1
 */
type SquashedMessage = Extract<AgentMessage, { role: "user" | "assistant" }>;

export function selectSquashedMessages(messages: readonly AgentMessage[]): SquashedMessage[] {
	const selected: SquashedMessage[] = [];
	let latestAssistant: Extract<AgentMessage, { role: "assistant" }> | undefined;
	for (const message of messages) {
		if (message.role === "assistant" && roleMessageText(message).trim()) {
			latestAssistant = message;
			continue;
		}
		if (message.role !== "user") continue;
		if (latestAssistant) selected.push(latestAssistant);
		latestAssistant = undefined;
		selected.push(message);
	}
	if (latestAssistant) selected.push(latestAssistant);
	return selected;
}

export function buildMessageDetails(agent: RunningAgent, ok: boolean): AgentCommandDetails {
	return {
		agentId: agent.id,
		command: agent.command,
		mainContextState: agent.mainContextState,
		inheritedContext: agent.inheritedContext,
		model: agent.model,
		modelLabel: agent.modelLabel,
		task: agent.task,
		ok,
		durationMs: (agent.completedAt ?? Date.now()) - agent.turnStartedAt,
		toolUses: agent.toolUses,
		turnCount: agent.turnCount,
		responseText: ok ? agent.responseText : undefined,
		error: ok ? undefined : agent.error,
	};
}

/** Build the canonical parent-session message used by immediate and late result delivery. */
export function buildAgentResultMessage(
	agent: RunningAgent,
	outcome: { ok: true; response: string } | { ok: false; error: string },
	options: { display: boolean },
): AgentResultMessage {
	return {
		customType: MESSAGE_TYPE,
		content: outcome.ok
			? formatResultMessage(agent)
			: formatErrorMessage(agent, outcome.error),
		display: options.display,
		details: buildMessageDetails(agent, outcome.ok),
	};
}

const SQUASHED_CONVERSATION_PREFACE =
	"The user has dispatched a background sub-agent with a task. The sub-agent is done. The following is the back and forth between them:";

export function formatResultMessage(agent: RunningAgent): string {
	const messages = selectSquashedMessages(agent.conversationMessages);
	const lines = [
		SQUASHED_CONVERSATION_PREFACE,
		`<user_agent model="${escapeAttribute(agent.model)}" inherited_context="${agent.inheritedContext}">`,
	];
	let firstUserMessage = true;
	for (const [index, message] of messages.entries()) {
		const tag = message.role === "user" ? "user_message" : "assistant_response";
		const content =
			message.role === "user" && firstUserMessage ? agent.task : roleMessageText(message);
		if (message.role === "user") firstUserMessage = false;
		lines.push(
			`  <${tag} i=${index + 1}>`,
			...content.split("\n").map((line) => `  ${line}`),
			`  </${tag}>`,
		);
	}
	lines.push("</user_agent>");
	return lines.join("\n");
}

function roleMessageText(message: SquashedMessage): string {
	if (typeof message.content === "string") return message.content;
	return message.content
		.flatMap((part) => (part.type === "text" ? [part.text] : []))
		.join("\n");
}

export function formatErrorMessage(agent: RunningAgent, message: string): string {
	return [
		`<user_agent_error command="/${agent.command}" model="${escapeAttribute(agent.model)}" inherited_context="${agent.inheritedContext}">`,
		...invocationLines(agent),
		"<task>",
		agent.task,
		"</task>",
		"<error>",
		message,
		"</error>",
		"<duration_ms>",
		String((agent.completedAt ?? Date.now()) - agent.turnStartedAt),
		"</duration_ms>",
		"</user_agent_error>",
	].join("\n");
}

function invocationLines(agent: RunningAgent): string[] {
	return ["<user_invocation>", agent.invocation, "</user_invocation>"];
}

export function formatCommandErrorMessage(
	command: AgentCommandName,
	args: string,
	message: string,
): string {
	return [
		`<user_agent_error command="/${command}">`,
		"<task>",
		args.trim(),
		"</task>",
		"<error>",
		message,
		"</error>",
		"</user_agent_error>",
	].join("\n");
}

export function formatStartNotification(agent: RunningAgent): string {
	return [
		`Started /${agent.command}`,
		agent.modelLabel,
		contextLabel(agent.inheritedContext),
		mainContextLabel(agent.mainContextState),
	]
		.filter(Boolean)
		.join(" · ");
}

export function registerUserAgentRenderer(pi: ExtensionAPI): void {
	pi.registerMessageRenderer<AgentCommandDetails>(
		MESSAGE_TYPE,
		(message, { expanded }, theme) =>
			liveAgentCard(
				() => customMessageContentText(message.content),
				() => message.details,
				expanded,
				theme,
			),
	);
	pi.registerEntryRenderer<AgentEntryData>(
		MESSAGE_TYPE,
		(entry, { expanded }, theme) =>
			entry.data
				? liveAgentCard(
						() => entry.data!.content,
						() => entry.data!.details,
						expanded,
						theme,
					)
				: undefined,
	);
	// Pi's chat container does not pad renderer components; its own chat lines self-pad with paddingX 1.
	pi.registerEntryRenderer<DetachedEntryData>(DETACHED_ENTRY_TYPE, (entry, _state, theme) =>
		entry.data
			? new Text(theme.fg("dim", `Detached session ${entry.data.sessionId}`), 1, 0)
			: undefined,
	);
	pi.registerEntryRenderer<AttachedEntryData>(ATTACHED_ENTRY_TYPE, (entry, _state, theme) =>
		entry.data
			? new Text(theme.fg("dim", `Attached session ${entry.data.sessionId}`), 1, 0)
			: undefined,
	);
	pi.registerEntryRenderer<RebasedEntryData>(REBASED_ENTRY_TYPE, (entry, _state, theme) =>
		entry.data ? new Text(theme.fg("dim", formatRebasedLine(entry.data)), 1, 0) : undefined,
	);
}

function formatRebasedLine(data: RebasedEntryData): string {
	const base = `Rebased session ${data.sessionId} into this conversation`;
	if (!data.stats) return base;
	const parts = [
		`added ${data.stats.messageCount} message${data.stats.messageCount === 1 ? "" : "s"}`,
		`~${formatTokenCount(data.stats.tokenEstimate)} tokens`,
	];
	if (data.stats.compactionCount > 0)
		parts.push(
			`${data.stats.compactionCount} compaction event${data.stats.compactionCount === 1 ? "" : "s"}`,
		);
	return `${base} (${parts.join(", ")})`;
}

/**
 * @example formatTokenCount(135_264) // "135K"
 * @example formatTokenCount(12) // "12"
 */
function formatTokenCount(tokens: number): string {
	return tokens < 1000 ? `${tokens}` : `${Math.round(tokens / 1000)}K`;
}

function liveAgentCard(
	content: () => string,
	details: () => AgentCommandDetails | undefined,
	expanded: boolean,
	theme: Theme,
): Component {
	const body = renderAgentCardBody(content(), details(), expanded, theme);
	return {
		render: (width) => renderAgentCard(content(), details(), body, theme).render(width),
		invalidate: () => body.invalidate(),
	};
}

function renderAgentCard(
	content: string,
	details: AgentCommandDetails | undefined,
	body: Component,
	theme: Theme,
): Container {
	const ok = details?.ok ?? !content.includes("<user_agent_error");
	const command = details ? `/${details.command}` : "/agent";
	const icon = ok ? theme.fg("success", "✓") : theme.fg("error", "✗");
	const statusText = ok ? theme.fg("dim", "completed") : theme.fg("error", "failed");
	const parts = buildRendererParts(content, details);
	const task = details?.task ?? extractTag(content, "task");

	let text = `${icon} ${theme.bold(command)} ${statusText}`;
	if (parts.length > 0) text += ` ${theme.fg("dim", "·")} ${theme.fg("dim", parts.join(" · "))}`;
	if (task) text += `\n  ${theme.fg("dim", `task: ${truncatePlain(task, 88)}`)}`;
	const card = new Container();
	card.addChild(new Text(text, 1, 0));
	card.addChild(body);
	return card;
}

function renderAgentCardBody(
	content: string,
	details: AgentCommandDetails | undefined,
	expanded: boolean,
	theme: Theme,
): Component {
	const ok = details?.ok ?? !content.includes("<user_agent_error");
	const output =
		details?.responseText ??
		details?.error ??
		extractTag(content, ok ? "response" : "error") ??
		"No output.";
	if (expanded)
		return ok
			? new Markdown(output, 3, 0, getMarkdownTheme())
			: new Text(theme.fg("error", output), 3, 0);

	const previewText = `⎿  ${truncatePlain(details?.responsePreview ?? output, 110)}`;
	if (!ok) return new Text(`  ${theme.fg("error", previewText)}`, 1, 0);
	return new Markdown(previewText, 3, 0, getMarkdownTheme(), {
		color: (value) => theme.fg("dim", value),
	});
}

function customMessageContentText(content: unknown): string {
	if (typeof content === "string") return content;
	if (!Array.isArray(content)) return String(content ?? "");
	return content
		.filter(
			(part): part is { type: "text"; text: string } =>
				part?.type === "text" && typeof part.text === "string",
		)
		.map((part) => part.text)
		.join("\n");
}

function buildRendererParts(content: string, details: AgentCommandDetails | undefined): string[] {
	const parts: string[] = [];
	if (details?.modelLabel) parts.push(details.modelLabel);
	else if (details?.model) parts.push(details.model);
	if (details?.inheritedContext !== undefined) parts.push(contextLabel(details.inheritedContext));
	const mainContext = mainContextLabel(details?.mainContextState);
	if (mainContext) parts.push(mainContext);
	if (details?.turnCount) parts.push(formatTurns(details.turnCount));
	if (details?.toolUses) parts.push(formatToolUses(details.toolUses));
	if (details?.durationMs !== undefined) parts.push(formatMs(details.durationMs));
	else {
		const duration = extractTag(content, "duration_ms");
		if (duration) parts.push(formatMs(Number(duration)));
	}
	return parts;
}
import type { CompletedAgent, RunningAgent, Theme } from "./shared.js";

const CONTEXT_METER_SYMBOLS = [" ", "▁", "▂", "▃", "▄", "▅", "▆", "▇", "█"] as const;
const CONTEXT_MUTED_THRESHOLD = 40;
const CONTEXT_WARNING_THRESHOLD = 65;
const CONTEXT_ERROR_THRESHOLD = 85;

type ContextMeterAgent = RunningAgent | CompletedAgent;
type ContextMeterColor = "dim" | "muted" | "warning" | "error";

/** @example contextMeterColor(85) // "error" */
export function contextMeterColor(percent: number): ContextMeterColor {
	if (percent >= CONTEXT_ERROR_THRESHOLD) return "error";
	if (percent >= CONTEXT_WARNING_THRESHOLD) return "warning";
	if (percent >= CONTEXT_MUTED_THRESHOLD) return "muted";
	return "dim";
}

export function renderContextMeter(
	percent: number | null | undefined,
	theme: Pick<Theme, "fg">,
): string {
	if (percent === null || percent === undefined) return "";
	const boundedPercent = Math.max(0, Math.min(100, percent));
	const level = Math.min(
		CONTEXT_METER_SYMBOLS.length - 1,
		Math.floor(boundedPercent / (100 / CONTEXT_METER_SYMBOLS.length)),
	);
	return theme.fg(contextMeterColor(boundedPercent), CONTEXT_METER_SYMBOLS[level]);
}

/** Render the current or final context usage for either agent state. */
export function renderAgentContextMeter(
	agent: ContextMeterAgent,
	theme: Pick<Theme, "fg">,
): string {
	const percent = "status" in agent
		? agent.session?.getContextUsage()?.percent
		: agent.contextPercent;
	return renderContextMeter(percent, theme);
}
"}

