			"0199aaaa-8b1a-7c3d-9e05-6a2f18d7b4ce",
		]);
		expect(widget.matchAttachedSessionIds("0199bbbb")).toEqual([
			"0199bbbb-1111-7abc-9e05-6a2f18d7b4ce",
		]);
		expect(widget.matchAttachedSessionIds("0199").sort()).toEqual([
			"0199aaaa-8b1a-7c3d-9e05-6a2f18d7b4ce",
			"0199bbbb-1111-7abc-9e05-6a2f18d7b4ce",
