			subscribe: (handler: (event: unknown) => void) => {
				listener = handler;
				return () => undefined;
			},
			getContextUsage: () => undefined,
		} as unknown as NonNullable<RunningAgent["session"]>;
		const agent = {
			id: "user-1",
			sessionId: "session-1",
