/**
 * Automatically name Pi sessions and project their names into Herdr.
 *
 * The Claude, Codex, and Pi implementations share this policy. Only lifecycle events,
 * session storage, and model calls differ. Pi reads and writes names through the extension
 * session API.
 *
 * Any session name matching `^\[.+\]` is authoritative. The broad match marks intentional
 * names without interpreting their prefix contents. Reuse that name without a model call and
 * project it to Herdr. This makes repeated runs idempotent.
 *
 * A plain name is non-authoritative, so generate the intentional name and replace it. If a
 * different name appears during generation, log it with the session ID to
 * `/tmp/pi-auto-session-name.log`. Then replace it with the intentional name.
 *
 * Generated session names use `[MM-DD][CWD] <imperative>`. Herdr labels remove the leading
 * date. Projection always renames the current pane. It renames the current tab when the pane
 * is first. It renames the current workspace when the tab is first and the workspace name is
 * numeric or the CWD. The workspace guard preserves curated names.
 */

import { appendFile } from "node:fs/promises";
import { basename } from "node:path";
import { completeSimple, type Message } from "@mariozechner/pi-ai";
import {
	convertToLlm,
	type ExtensionAPI,
	type ExtensionContext,
	type ExtensionHandler,
	type InputEvent,
	type InputEventResult,
	type SessionEntry,
	serializeConversation,
	type SessionStartEvent,
} from "@mariozechner/pi-coding-agent";

const MAX_SESSION_NAME_LENGTH = 150;
const MODEL_PROVIDER = "openai-codex";
const MODEL_ID = "gpt-5.6-luna";
const TEMP_NAME = "[generating name…]";
const MID_PROCESS_WARNING_LOG = "/tmp/pi-auto-session-name.log";
const PROMPT = "Name this session. The format is `<verb> <one lowercase phrase expressing the purpose of the session in its entirety — the end state the user wants to achieve>`.\nClarification about <verb>: a single lowercase word pinning down the type of the session’s task.";

type SessionNameResult = { name?: string; warning?: string };
type NamingRequest = {
	sessionId: string;
	cwdName: string;
	transcript: string;
	startedAt: number;
	nameBeforeGeneration: string | undefined;
};
type PendingNamingRequest = {
	abortController: AbortController;
	task: Promise<void>;
};
type ExistingSessionNameAction =
	| { kind: "project"; name: string }
	| { kind: "generate" }
	| { kind: "wait" };
type HerdrRuntime = Pick<ExtensionAPI, "exec">;
export type HerdrIdentity = {
	paneId: string;
	tabId: string;
	workspaceId: string;
};
export type HerdrRenameTarget = {
	level: "pane" | "tab" | "workspace";
	id: string;
};
type HerdrPaneResponse = {
	result: { pane: { pane_id: string; tab_id: string; workspace_id: string } };
};
type HerdrPaneLayoutResponse = {
	result: { layout: { panes: Array<{ pane_id: string }> } };
};
type HerdrTabListResponse = {
	result: { tabs: Array<{ tab_id: string; number: number }> };
};
type HerdrWorkspaceResponse = {
	result: { workspace: { label?: string } };
};

/**
 * Session-name lifecycle:
 *
 * Both hooks project a bracket-prefixed existing name or start a session-scoped background
 * LLM call. The request is aborted during session_shutdown before Pi invalidates the
 * extension context. TEMP_NAME is cleared on every failure path so the placeholder never sticks.
 */
export default function (pi: ExtensionAPI) {
	let pendingNamingRequest: PendingNamingRequest | undefined;

	const cancelPendingNamingRequest = () => {
		pendingNamingRequest?.abortController.abort();
	};

	const startNamingRequest = (request: NamingRequest, ctx: ExtensionContext) => {
		cancelPendingNamingRequest();
		const abortController = new AbortController();
		const task = requestSessionName(request, ctx, abortController.signal)
			.then(async (result) => {
				if (abortController.signal.aborted) return;
				await applySessionNameResult(result, request, ctx, pi);
			})
			.catch((error) => {
				if (abortController.signal.aborted) return;
				clearTemporarySessionName(pi);
				const message = error instanceof Error ? error.message : String(error);
				ctx.ui.notify(`auto-session-name: ${message}`, "error");
			})
			.finally(() => {
				if (pendingNamingRequest?.abortController === abortController) {
					pendingNamingRequest = undefined;
				}
			});
		pendingNamingRequest = { abortController, task };
	};

	const projectSessionName = async (sessionName: string, ctx: ExtensionContext) => {
		try {
			await applyHerdrLabel(herdrLabelFromSessionName(sessionName), pi, basename(ctx.cwd));
		} catch (error) {
			ctx.ui.notify(
				`auto-session-name: ${error instanceof Error ? error.message : String(error)}`,
				"error",
			);
		}
	};

	const ensureSessionName: ExtensionHandler<InputEvent, InputEventResult> = async (event, ctx) => {
		if (!shouldAutoName(event, ctx, pi)) return { action: "continue" };
		const nameBeforeGeneration = pi.getSessionName();
		const action = sessionNameAction(nameBeforeGeneration);
		if (action.kind === "wait") return { action: "continue" };
		if (action.kind === "project") {
			await projectSessionName(action.name, ctx);
			return { action: "continue" };
		}
		const request = buildNamingRequest(event.text, ctx, nameBeforeGeneration);
		pi.setSessionName(TEMP_NAME);
		startNamingRequest(request, ctx);

		return { action: "continue" };
	};
	pi.on("input", ensureSessionName);
	pi.on("session_start", async (event: SessionStartEvent, ctx: ExtensionContext) => {
		if (event.reason === "new") return;
		if (!hasPersistentSession(ctx)) return;

		const nameBeforeGeneration = pi.getSessionName();
		const action = sessionNameAction(nameBeforeGeneration);
		if (action.kind === "wait") return;
		if (action.kind === "project") {
			await projectSessionName(action.name, ctx);
			return;
		}

		const hasMessages = ctx.sessionManager
			.getBranch()
			.some((entry) => entry.type === "message");
		if (!hasMessages) return;

		const request = buildNamingRequest(undefined, ctx, nameBeforeGeneration);
		pi.setSessionName(TEMP_NAME);
		startNamingRequest(request, ctx);
	});

	pi.on("session_shutdown", async () => {
		const request = pendingNamingRequest;
		request?.abortController.abort();
		clearTemporarySessionName(pi);
		await request?.task;
	});

	pi.registerCommand("autoname", {
		description: "Auto-name the current session using an LLM",
		handler: async (_args, ctx) => {
			const hasMessages = ctx.sessionManager
				.getBranch()
				.some((entry) => entry.type === "message");
			if (!hasMessages) {
				ctx.ui.notify("auto-session-name: no messages to name from", "warning");
				return;
			}

			const currentName = pi.getSessionName();
			if (currentName && currentName !== TEMP_NAME) {
				const overwrite = await ctx.ui.confirm(
					`"${currentName}"`,
					"Overwrite with an auto-generated name?",
				);
				if (!overwrite) return;
			}
			const request = buildNamingRequest(undefined, ctx, currentName);
			pi.setSessionName(TEMP_NAME);
			try {
				const result = await requestSessionName(request, ctx, ctx.signal);
				await applySessionNameResult(result, request, ctx, pi);
			} catch (error) {
				clearTemporarySessionName(pi);
				const message = error instanceof Error ? error.message : String(error);
				ctx.ui.notify(`auto-session-name: ${message}`, "error");
			}
		},
	});
}

function shouldAutoName(
	event: { source: string; text: string },
	ctx: ExtensionContext,
	pi: ExtensionAPI,
): boolean {
	if (event.source === "extension") return false;
	if (!hasPersistentSession(ctx)) return false;
	if (pi.getSessionName() === TEMP_NAME) return false;

	// Heuristic: detect (and abort on) messages that are only a command, without instructions.
	if (event.text.trim().startsWith("/") && event.text.split(" ").length <= 3) return false;
	return true;
}

function hasPersistentSession(ctx: ExtensionContext): boolean {
	return ctx.sessionManager.getSessionFile() !== undefined;
}

function clearTemporarySessionName(pi: ExtensionAPI): void {
	if (pi.getSessionName() === TEMP_NAME) pi.setSessionName("");
}

function buildNamingRequest(
	eventText: string | undefined,
	ctx: ExtensionContext,
	nameBeforeGeneration: string | undefined,
): NamingRequest {
	const firstMessage = ctx.sessionManager
		.getBranch()
		.find((entry): entry is SessionEntry & { type: "message" } => entry.type === "message");
	const namingRequest = {
		sessionId: ctx.sessionManager.getSessionId(),
		cwdName: basename(ctx.cwd),
		transcript: _buildTranscript(eventText, ctx),
		startedAt: firstMessage?.message.timestamp ?? Date.now(),
		nameBeforeGeneration,
	};
	return namingRequest;
}

function _buildTranscript(eventText: string | undefined, ctx: ExtensionContext): string {
	const branchMessages = ctx.sessionManager
		.getBranch()
		.filter((entry): entry is SessionEntry & { type: "message" } => entry.type === "message")
		.map((entry) => entry.message);
	if (!!eventText) {
		branchMessages.push({
			role: "user",
			content: [{ type: "text", text: eventText }],
			timestamp: Date.now(),
		});
	}
	return serializeConversation(convertToLlm(branchMessages));
}

async function requestSessionName(
	request: NamingRequest,
	ctx: ExtensionContext,
	signal?: AbortSignal,
): Promise<SessionNameResult> {
	const model = ctx.modelRegistry.find(MODEL_PROVIDER, MODEL_ID);
	if (!model) throw new Error(`Model not found: ${MODEL_PROVIDER}/${MODEL_ID}`);

	const auth = await ctx.modelRegistry.getApiKeyAndHeaders(model);
	if (!auth.ok) throw new Error(auth.error);
	if (!auth.apiKey) throw new Error(`No API key for ${MODEL_PROVIDER}/${MODEL_ID}`);

	let response: Awaited<ReturnType<typeof completeSimple>> | undefined;
	const retry = 2;
	for (let attempt = 1; attempt <= retry; attempt++) {
		try {
			response = await completeSimple(
				model,
				{ messages: [_buildPrompt(request.transcript, request.cwdName)] },
				{ apiKey: auth.apiKey, headers: auth.headers, signal, reasoning: "medium" },
			);
			break;
		} catch (error) {
			if (signal?.aborted) throw error;
			if (attempt === retry) {
				throw new Error(
					`Error requesting session name: ${error instanceof Error ? error.message : String(error)}`,
				);
			}
		}
	}
	if (!response) throw new Error("Error requesting session name: empty response");

	const outputText = response.content
		.filter((block): block is { type: "text"; text: string } => block.type === "text")
		.map((block) => block.text)
		.join("\n");
	return _parseSessionNameOutput(outputText, request.cwdName);
}

function _buildPrompt(transcript: string, cwdName: string): Message {
	return {
		role: "user",
		content: [
			{
				type: "text",
				text:
					"<transcript-of-session-to-name>\n" +
					transcript +
					"\n" +
					"</transcript-of-session-to-name>\n\n" +
					"===\n\n" +
					"<task>\n" +
					PROMPT +
					"\n\n" +
					"The session working directory name is: " +
					cwdName +
					"\n" +
					"</task>",
			},
		],
		timestamp: Date.now(),
	};
}

function _parseSessionNameOutput(outputText: string, cwdName: string): SessionNameResult {
	const outputLines = _cleanLine(outputText).split("\n").map(_cleanLine).filter(Boolean);

	if (outputLines.length === 0) {
		return {
			warning: "auto-session-name: model returned empty output; session not named",
		};
	}

	const picked =
		outputLines.length === 1
			? outputLines[0]
			: outputLines.length === 2 && outputLines[0]?.endsWith(":")
				? outputLines[1]
				: undefined;
	if (!picked) {
		return {
			warning: `auto-session-name: could not pick a session name from model output:\n${outputText}`,
		};
	}
	if (picked.toLowerCase() === cwdName.toLowerCase()) {
		return {
			warning: `auto-session-name: refusing useless session name output:\n${outputText}`,
		};
	}
	return { name: picked };
}

function _cleanLine(line: string): string {
	return line
		.trim()
		.replace(/^['"]+|['"]+$/g, "")
		.replace(/^`+|`+$/g, "")
		.slice(0, MAX_SESSION_NAME_LENGTH)
		.trim();
}

async function applySessionNameResult(
	result: SessionNameResult,
	request: NamingRequest,
	ctx: ExtensionContext,
	pi: ExtensionAPI,
): Promise<void> {
	if (result.warning) {
		clearTemporarySessionName(pi);
		ctx.ui.notify(result.warning, "warning");
		return;
	}
	if (!result.name) {
		clearTemporarySessionName(pi);
		return;
	}
	if (ctx.sessionManager.getSessionId() !== request.sessionId) {
		clearTemporarySessionName(pi);
		ctx.ui.notify(
			"auto-session-name: session changed before name resolved; session not named",
			"warning",
		);
		return;
	}
	const midProcessName = sessionNameAddedDuringGeneration(
		request.nameBeforeGeneration,
		pi.getSessionName(),
	);
	if (midProcessName) await logMidProcessName(request.sessionId, midProcessName);
	const fullName = `[${_datePrefix(request.startedAt)}][${request.cwdName}] ${result.name}`;
	pi.setSessionName(fullName);
	pi.events.emit("session:name-changed", { name: fullName });
	await applyHerdrLabel(
		`[${request.cwdName}] ${result.name}`,
		pi,
		request.cwdName,
	);
}

async function logMidProcessName(sessionId: string, name: string): Promise<void> {
	await appendFile(
		MID_PROCESS_WARNING_LOG,
		`[${new Date().toISOString()}] WARNING [${sessionId}] ignored session name generated mid-process: ${JSON.stringify(name)}\n`,
	);
}

export function herdrRenameTargets(
	currentPaneIsFirst: boolean,
	currentTabIsFirst: boolean,
	workspaceIsDefault: boolean,
	identity: HerdrIdentity,
): HerdrRenameTarget[] {
	const targets: HerdrRenameTarget[] = [{ level: "pane", id: identity.paneId }];
	if (currentPaneIsFirst) targets.push({ level: "tab", id: identity.tabId });
	if (currentTabIsFirst && workspaceIsDefault) {
		targets.push({ level: "workspace", id: identity.workspaceId });
	}
	return targets;
}

/** @example isDefaultWorkspaceName("1", "hooks") // true */
export function isDefaultWorkspaceName(label: string | undefined, cwdName: string): boolean {
	return label === cwdName || Boolean(label && /^\d+$/u.test(label));
}

/**
 * @example
 * herdrPosition(
 *   { paneId: "p1", tabId: "t1", workspaceId: "w1" },
 *   [{ pane_id: "p1" }],
 *   [{ tab_id: "t1", number: 1 }],
 * ) // { currentPaneIsFirst: true, currentTabIsFirst: true }
 */
export function herdrPosition(
	identity: HerdrIdentity,
	panes: Array<{ pane_id: string }>,
	tabs: Array<{ tab_id: string; number: number }>,
): { currentPaneIsFirst: boolean; currentTabIsFirst: boolean } {
	const firstTab = tabs.reduce((first, tab) => (tab.number < first.number ? tab : first));
	return {
		currentPaneIsFirst: panes[0]!.pane_id === identity.paneId,
		currentTabIsFirst: firstTab.tab_id === identity.tabId,
	};
}

export function herdrLabelFromSessionName(sessionName: string): string {
	// Drop the `[mm-dd]` date prefix a session name carries, leaving its Herdr-label form.
	return sessionName.replace(/^\[\d\d-\d\d\]\s*/u, "").trim();
}

/** @example prefixedSessionName("[09-02][top] fix naming") // "[09-02][top] fix naming" */
export function prefixedSessionName(sessionName: string | undefined): string | undefined {
	return sessionName && /^\[.+\]/u.test(sessionName) ? sessionName : undefined;
}

export function sessionNameAction(sessionName: string | undefined): ExistingSessionNameAction {
	if (sessionName === TEMP_NAME) return { kind: "wait" };
	const preservedName = prefixedSessionName(sessionName);
	return preservedName
		? { kind: "project", name: preservedName }
		: { kind: "generate" };
}

export function sessionNameAddedDuringGeneration(
	nameBeforeGeneration: string | undefined,
	currentName: string | undefined,
): string | undefined {
	if (!currentName || currentName === TEMP_NAME || currentName === nameBeforeGeneration) return;
	return currentName;
}

async function applyHerdrLabel(
	label: string,
	pi: ExtensionAPI,
	cwdName: string,
): Promise<void> {
	const identity = await herdrPaneIdentity(pi);
	if (!identity) return;

	const layout = JSON.parse(
		await runHerdr(pi, ["pane", "layout", "--pane", identity.paneId]),
	) as HerdrPaneLayoutResponse;
	const tabList = JSON.parse(
		await runHerdr(pi, ["tab", "list", "--workspace", identity.workspaceId]),
	) as HerdrTabListResponse;
	const workspace = JSON.parse(
		await runHerdr(pi, ["workspace", "get", identity.workspaceId]),
	) as HerdrWorkspaceResponse;
	const position = herdrPosition(identity, layout.result.layout.panes, tabList.result.tabs);
	const workspaceIsDefault = isDefaultWorkspaceName(workspace.result.workspace.label, cwdName);
	const targets = herdrRenameTargets(
		position.currentPaneIsFirst,
		position.currentTabIsFirst,
		workspaceIsDefault,
		identity,
	);
	for (const target of targets) {
		await runHerdr(pi, [target.level, "rename", target.id, label]);
	}
}

export async function herdrPaneIdentity(pi: HerdrRuntime): Promise<HerdrIdentity | undefined> {
	if (process.env.HERDR_ENV !== "1" || !process.env.HERDR_SOCKET_PATH) return;

	const paneId = process.env.HERDR_PANE_ID?.trim();
	if (!paneId) return;
	const response = JSON.parse(
		await runHerdr(pi, ["pane", "get", paneId]),
	) as HerdrPaneResponse;
	return {
		paneId: response.result.pane.pane_id,
		tabId: response.result.pane.tab_id,
		workspaceId: response.result.pane.workspace_id,
	};
}

async function runHerdr(pi: HerdrRuntime, args: string[]): Promise<string> {
	const result = await pi.exec("herdr", args, { timeout: 15_000 });
	if (result.code !== 0) {
		throw new Error(`herdr ${args.join(" ")} failed: ${result.stderr.slice(0, 300)}`);
	}
	return result.stdout;
}

function _datePrefix(startedAt: number): string {
	// ponytail: en-US 2-digit month/day always formats as "MM/DD".
	const [month, day] = new Intl.DateTimeFormat("en-US", {
		timeZone: "Asia/Jerusalem",
		month: "2-digit",
		day: "2-digit",
	})
		.format(new Date(startedAt))
		.split("/");
	return `${month}-${day}`;
}

